import{_ as o,o as a,c as t,ae as i}from"./chunks/framework.DCJ5T8RY.js";const u=JSON.parse('{"title":"一次搞笑而深刻的bug调试","description":"","frontmatter":{"title":"一次搞笑而深刻的bug调试","date":"2018-05-04"},"headers":[],"relativePath":"2018/funny-bug-debugging.md","filePath":"2018/funny-bug-debugging.md","lastUpdated":1786185344000}'),s={name:"2018/funny-bug-debugging.md"};function l(p,e,r,n,c,d){return a(),t("div",null,[...e[0]||(e[0]=[i('<h4 id="问题出现" tabindex="-1">问题出现 <a class="header-anchor" href="#问题出现" aria-label="Permalink to &quot;问题出现&quot;">​</a></h4><blockquote><p>APP 某个页面加载时访问了 2 个 API，两者的返回数据都分别有<code>type</code>字段，用于区分对应的数据列表中项目的类别，前端界面再根据类别渲染不同的界面</p></blockquote><p>这个时候问题出现了，第一个 API 一切正常，第二个 API 返回列表本应全是<code>type=1</code>的数据类型，但是每次返回的第一条数据都是<code>type=2</code></p><h4 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h4><ol><li><p>很自然打开<code>chrome devTool</code>，打印并查看后台返回数据，嗯，返回的数据<code>type=2</code>，看来是后台问题可能性较大</p></li><li><p>再次确认，用<code>postman</code>请求一次接口看看返回数据，咦，怎么返回数据又对了，<code>type=1</code>，反复试了几次，还是对的</p></li><li><p>换了一个 API 测试工具，结果和 2 一样，看样子应该是前端的问题了，而且应该是网络层的问题，而网络层是基于 axios 封装的，也就是说 axios 有问题？</p></li><li><p>还是觉得需要首先排除后台原因，于是让后台同事打印出接口返回数据，对比之后发现和 API 工具结果一致，基本排除后端责任</p></li><li><p>深入到封装的网络层查看<code>axios</code>返回的数据，链式函数里淘宝，分别打印了<code>response=&gt;response.data</code>，二者数据一致错误，数据 bug 复现</p></li><li><p>怀疑 axios 老版本不可靠，于是升级到最新版，继续测试，问题依旧</p></li><li><p>开始 axios 请求的头部是<code>json</code>，移植之前封装的另一版本网络层代码，头部使用<code>arraybuffer</code>, 解码后<code>response</code>的数据与后台一致了， 但是<code>response.data</code>数据仍错误，因为二者间只多了一次<code>JSON.parse</code>,定位问题在<code>JSON.parse</code></p></li><li><p>因为 JSON.parse 本身不会有问题，再次开始怀疑 bug 源于后端，返回的 json 字符串格式不标准导致解析错误，可用解析工具可以顺利解析出 json，这里没有问题</p></li><li><p>病急乱投医，怀疑 2 个接口同时请求有问题，于是注释第一个正常 API 的所有网络访问代码，返回结果一致，看来接口没有相关性，问题独立出现在第二个接口上</p></li><li><p>复制 API 调试工具的返回 json，同时网络层截断发往结果异常 API 接口的所有网络访问，把复制的 json 作为固定数据返回给 <code>response</code>，错误依旧，问题确定位在前端了</p></li><li><p>把 10 中的 json 里的 type 属性改名为 mode，axios 解析的数据正常了</p></li><li><p>继续看 axios 封装内容，<code>.then(response=&gt;{...})</code>同时打印<code>response， JSON.parse(response.data)</code>, 数据又正确了，并且打印出数据一致。 基本排除 axios 错误的可能性，那么就只剩下前端页面代码 bug 这一种可能性了，开始从网络层逐渐向应用层排查</p></li><li><p>最后可耻的在 reducer 里发现了自己写死的代码<code>response[0].type = 2</code>, 根源找到</p></li></ol><p><strong>总耗时： 8 小时</strong></p><h4 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to &quot;原因&quot;">​</a></h4><p>简单说就是 chrome 的 console.log 打印对象时，如果对象后续值被修改了，打印的值也会随之改变，除非打印时就立刻展开对象的所有属性</p><p><code>stackoverflow</code>找到了问题，这个问题（或者说 bug）起源于 webkit 的一个 bug <a href="https://stackoverflow.com/questions/11284663/console-log-shows-the-changed-value-of-a-variable-before-the-value-actually-ch%5D" target="_blank" rel="noreferrer"><code>stackoverflow问题地址</code></a></p><blockquote><p>Excerpts from the original bug report ([<a href="https://bugs.webkit.org/show_bug.cgi?id=35801" target="_blank" rel="noreferrer">https://bugs.webkit.org/show_bug.cgi?id=35801</a>]):</p><p>Description From mitch kramer 2010-03-05 11:37:45 PST</p><ol><li><p>create an object literal with one or more properties</p></li><li><p>console.log that object but leave it closed (don&#39;t expand it in the console)</p></li><li><p>change one of the properties to a new value</p></li></ol><p>now open that console.log and you&#39;ll see it has the new value for some reason, even though it&#39;s value was different at the time it was generated.</p><p>I should point out that if you open it, it will retain the correct value if that wasn&#39;t clear.</p></blockquote><h4 id="规避方法" tabindex="-1">规避方法 <a class="header-anchor" href="#规避方法" aria-label="Permalink to &quot;规避方法&quot;">​</a></h4><ul><li>创建对象的一个深拷贝，使它不受后续的影响， 比如把对象转成字符串再读取回来</li></ul><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">parse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stringify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(object));</span></span></code></pre></div><blockquote><h2 id="应验了一句老话-眼见也未必为实-今天体会很深" tabindex="-1">应验了一句老话，眼见也未必为实，今天体会很深 <a class="header-anchor" href="#应验了一句老话-眼见也未必为实-今天体会很深" aria-label="Permalink to &quot;应验了一句老话，眼见也未必为实，今天体会很深&quot;">​</a></h2></blockquote>',14)])])}const g=o(s,[["render",l]]);export{u as __pageData,g as default};
